import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static long nextLong() {
        while (buf[bp] <= ' ') bp++;
        boolean neg = buf[bp] == '-';
        if (neg) bp++;
        long r = 0;
        while (bp < buf.length && buf[bp] > ' ') r = r * 10 + (buf[bp++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong(), q = (int) nextLong();
        HashSet<Long> live = new HashSet<>(4 * n);
        long[] init = new long[n];
        for (int i = 0; i < n; i++) live.add(init[i] = nextLong());
        // A segment starts at every house without a left neighbour.
        int segments = 0;
        for (long x : init) if (!live.contains(x - 1)) segments++;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long x = nextLong();
            boolean left = live.contains(x - 1), right = live.contains(x + 1);
            if (left && right) segments++;        // a segment splits in two
            else if (!left && !right) segments--; // a single-house segment vanishes
            live.remove(x);
            if (i > 0) sb.append(' ');
            sb.append(segments);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n, q := int(next()), int(next())
	live := make(map[int64]bool, n)
	init := make([]int64, n)
	for i := range init {
		init[i] = next()
		live[init[i]] = true
	}
	// A segment starts at every house without a left neighbour.
	segments := 0
	for _, x := range init {
		if !live[x-1] {
			segments++
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		x := next()
		left, right := live[x-1], live[x+1]
		if left && right {
			segments++ // a segment splits in two
		} else if !left && !right {
			segments-- // a single-house segment vanishes
		}
		delete(live, x)
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(segments))
	}
	w.WriteByte('\n')
}
